package com.fasterxml.jackson.databind.deser;

import com.fasterxml.jackson.annotation.*;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.DeserializationContext;
import com.fasterxml.jackson.databind.JsonMappingException;
import com.fasterxml.jackson.databind.annotation.JsonPOJOBuilder;
import com.fasterxml.jackson.databind.cfg.ConfigOverride;
import com.fasterxml.jackson.databind.cfg.DeserializationConfig;
import com.fasterxml.jackson.databind.cfg.DeserializerFactoryConfig;
import com.fasterxml.jackson.databind.deser.BeanDescription;
import com.fasterxml.jackson.databind.deser.BeanDeserializerBuilder;
import com.fasterxml.jackson.databind.deser.impl.*;
import com.fasterxml.jackson.databind.deser.std.StdBeanPropertyDefinition;
import com.fasterxml.jackson.databind.deser.std.StdDeserializer;
import com.fasterxml.jackson.databind.deser.std.ThrowableDeserializer;
import com.fasterxml.jackson.databind.introspect.*;
import com.fasterxml.jackson.databind.jsontype.TypeDeserializer;
import com.fasterxml.jackson.databind.util.ClassUtil;
import com.fasterxml.jackson.databind.util.SimpleBeanPropertyDefinition;
import java.io.*;
import java.lang.reflect.Field;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.*;

public class BeanDeserializerFactory_filterBeanProps_TriageGen2Test {

    private BeanDeserializerFactory factory;
    private DeserializationContext ctxt;
    private DeserializationConfig config;
    private BeanDescription beanDesc;
    private BeanDeserializerBuilder builder;

    // Subclass to expose protected method for testing
    private static class TestableBeanDeserializerFactory extends BeanDeserializerFactory {
        public TestableBeanDeserializerFactory() {
            super(null);
        }

        @Override
        protected boolean isIgnorableType(DeserializationConfig config, BeanDescription beanDesc, Class<?> type, Map<Class<?>, Boolean> ignoredTypes) {
            // Implementation to allow us to control the branching logic in the test
            // We'll use a specific class name to trigger "true" for testing
            return type.getSimpleName().equals("IgnorableType");
        }

        @Override
        public List<BeanPropertyDefinition> filterBeanProps(DeserializationContext ctxt,
                                                           BeanDescription beanDesc,
                                                           BeanDeserializerBuilder builder,
                                                           List<BeanPropertyDefinition> propDefsIn,
                                                           Set<String> ignored) throws JsonMappingException {
            return super.filterBeanProps(ctxt, beanDesc, builder, propDefsIn, ignored);
        }
    }

    @Before
    public void setUp() {
        factory = new TestableBeanDeserializerFactory();
        ctxt = mock(DeserializationContext.class);
        config = mock(DeserializationConfig.class);
        beanDesc = mock(BeanDescription.class);
        builder = mock(BeanDeserializerBuilder.class);
        when(ctxt.getConfig()).thenReturn(config);
    }

    @Test
    public void testFilterBeanProps_AllPassed() throws JsonMappingException {
        BeanPropertyDefinition prop1 = mock(BeanPropertyDefinition.class);
        when(prop1.getName()).thenReturn("prop1");
        when(prop1.hasConstructorParameter()).thenReturn(true);

        BeanPropertyDefinition prop2 = mock(BeanPropertyDefinition.class);
        when(prop2.getName()).thenReturn("prop2");
        when(prop2.hasConstructorParameter()).thenReturn(false);
        when(prop2.hasSetter()).thenReturn(false);
        when(prop2.hasField()).thenReturn(false);

        List<BeanPropertyDefinition> input = Arrays.asList(prop1, prop2);
        Set<String> ignored = new HashSet<>();

        List<BeanPropertyDefinition> result = factory.filterBeanProps(ctxt, beanDesc, builder, input, ignored);

        assertEquals(2, result.size());
        assertTrue(result.contains(prop1));
        assertTrue(result.contains(prop2));
    }

    @Test
    public void testFilterBeanProps_ExplicitlyIgnored() throws JsonMappingException {
        BeanPropertyDefinition prop1 = mock(BeanPropertyDefinition.class);
        when(prop1.getName()).thenReturn("ignoredProp");

        BeanPropertyDefinition prop2 = mock(BeanPropertyDefinition.class);
        when(prop2.getName()).thenReturn("keepProp");
        when(prop2.hasConstructorParameter()).thenReturn(true);

        List<BeanPropertyDefinition> input = Arrays.asList(prop1, prop2);
        Set<String> ignored = Collections.singleton("ignoredProp");

        List<BeanPropertyDefinition> result = factory.filterBeanProps(ctxt, beanDesc, builder, input, ignored);

        assertEquals(1, result.size());
        assertEquals("keepProp", result.get(0).getName());
    }

    @Test
    public void testFilterBeanProps_IgnorableTypeViaSetter() throws JsonMappingException {
        // Setup a property that has a setter and returns an "IgnorableType"
        BeanPropertyDefinition prop = mock(BeanPropertyDefinition.class);
        when(prop.getName()).thenReturn("ignorableProp");
        when(prop.hasConstructorParameter()).thenReturn(false);
        when(prop.hasSetter()).thenReturn(true);

        BeanSetter setter = mock(BeanSetter.class);
        when(prop.getSetter()).thenReturn(setter);
        when(setter.getRawParameterType(0)).thenReturn(IgnorableType.class);

        List<BeanPropertyDefinition> input = Collections.singletonList(prop);
        Set<String> ignored = new HashSet<>();

        List<BeanPropertyDefinition> result = factory.filterBeanProps(ctxt, beanDesc, builder, input, ignored);

        assertTrue(result.isEmpty());
        verify(builder).addIgnorable("ignorableProp");
    }

    @Test
    public void testFilterBeanProps_IgnorableTypeViaField() throws JsonMappingException {
        BeanPropertyDefinition prop = mock(BeanPropertyDefinition.class);
        when(prop.getName()).thenReturn("ignorableFieldProp");
        when(prop.hasConstructorParameter()).thenReturn(false);
        when(prop.hasSetter()).thenReturn(false);
        when(prop.hasField()).thenReturn(true);

        BeanField field = mock(BeanField.class);
        when(prop.getField()).thenReturn(field);
        when(field.getRawType()).thenReturn(IgnorableType.class);

        List<BeanPropertyDefinition> input = Collections.singletonList(prop);
        Set<String> ignored = new HashSet<>();

        List<BeanPropertyDefinition> result = factory.filterBeanProps(ctxt, beanDesc, builder, input, ignored);

        assertTrue(result.isEmpty());
        verify(builder).addIgnorable("ignorableFieldProp");
    }

    @Test
    public void testFilterBeanProps_KeepConstructorParamEvenIfIgnorableType() throws JsonMappingException {
        // Even if the type is ignorable, if it's a constructor parameter, it should NOT be skipped
        BeanPropertyDefinition prop = mock(BeanPropertyDefinition.class);
        when(prop.getName()).thenReturn("constructorProp");
        when(prop.hasConstructorParameter()).thenReturn(true);
        // We simulate a scenario where the user might think it's ignorable, but constructor params are protected

        List<BeanPropertyDefinition> input = Collections.singletonList(prop);
        Set<String> ignored = new HashSet<>();

        List<BeanPropertyDefinition> result = factory.filterBeanProps(ctxt, beanDesc, builder, input, ignored);

        assertEquals(1, result.size());
        verify(builder, never()).addIgnorable(anyString());
    }

    @Test
    public void testFilterBeanProps_NullTypeHandling() throws JsonMappingException {
        BeanPropertyDefinition prop = mock(BeanPropertyDefinition.class);
        when(prop.getName()).thenReturn("nullTypeProp");
        when(prop.hasConstructorParameter()).thenReturn(false);
        when(prop.hasSetter()).thenReturn(true);

        BeanSetter setter = mock(BeanSetter.class);
        when(prop.getSetter()).thenReturn(setter);
        when(setter.getRawParameterType(0)).thenReturn(null);

        List<BeanPropertyDefinition> input = Collections.singletonList(prop);
        Set<String> ignored = new HashSet<>();

        List<BeanPropertyDefinition> result = factory.filterBeanProps(ctxt, beanDesc, builder, input, ignored);

        assertEquals(1, result.size());
        verify(builder, never()).addIgnorable(anyString());
    }

    // Helper classes/interfaces to satisfy mocks
    private static class IgnorableType {}

    private interface BeanSetter {
        Class<?> getRawParameterType(int i);
    }

    private interface BeanField {
        Class<?> getRawType();
    }
}
